import static org.hamcrest.CoreMatchers.is;
import static org.hamcrest.MatcherAssert.assertThat;

// Mock class for compilation
class DebugCoreMessages {
    public static String RuntimeProcess_terminate_failed = "Failed to terminate process";
}

public class TestClass {
    public void testAsserts() {
        String actualMessage = "Actual message";
        String expectedMessage = DebugCoreMessages.RuntimeProcess_terminate_failed;
        assertThat(actualMessage, is(expectedMessage));
    }

    public void anotherTest() {
        Object obj = new Object();
        assertThat(obj, is("some string"));
    }
}

