negativeExample:
import static org.hamcrest.CoreMatchers.containsString;
import static org.hamcrest.MatcherAssert.assertThat;
import static org.junit.Assert.assertFalse;

public class TestClass {
    public void testNotIsMatcher() {
        String actualValue = "hello world";
        assertThat(actualValue, containsString("hello")); // Uses 'containsString' matcher, not 'is'
    }

    public void testNoHamcrest() {
        // This is not a Hamcrest assertThat call
        assertFalse(false);
    }
}
